macro_rules! deps {
    () => {
        MapErr!();
        Filter!();
        Map!();
        MapRef!();
        FuseState!();
        Take!();
        Fuse!();
        Skip!();
        SkipWhile!();
        TakeWhile!();
    };
}

macro_rules! FallibleStreamingIterator {
    () => {
        deps!();
        # [doc = " A fallible, streaming iterator."] pub trait FallibleStreamingIterator { # [doc = " The type being iterated over."] type Item : ? Sized ; # [doc = " The error type of iteration."] type Error ; # [doc = " Advances the iterator to the next position."] # [doc = ""] # [doc = " Iterators start just before the first item, so this method should be called before `get`"] # [doc = " when iterating."] # [doc = ""] # [doc = " The behavior of calling this method after `get` has returned `None`, or after this method"] # [doc = " has returned an error is unspecified."] fn advance (& mut self) -> Result < () , Self :: Error > ; # [doc = " Returns the current element."] # [doc = ""] # [doc = " The behavior of calling this method before any calls to `advance` is unspecified."] fn get (& self) -> Option < & Self :: Item > ; # [doc = " Advances the iterator, returning the next element."] # [doc = ""] # [doc = " The default implementation simply calls `advance` followed by `get`."] # [inline] fn next (& mut self) -> Result < Option < & Self :: Item > , Self :: Error > { self . advance () ? ; Ok ((* self) . get ()) } # [doc = " Returns bounds on the number of remaining elements in the iterator."] # [inline] fn size_hint (& self) -> (usize , Option < usize >) { (0 , None) } # [doc = " Determines if all elements of the iterator satisfy a predicate."] # [inline] fn all < F > (& mut self , mut f : F) -> Result < bool , Self :: Error > where Self : Sized , F : FnMut (& Self :: Item) -> bool , { while let Some (e) = self . next () ? { if ! f (e) { return Ok (false) ; } } Ok (true) } # [doc = " Determines if any elements of the iterator satisfy a predicate."] # [inline] fn any < F > (& mut self , mut f : F) -> Result < bool , Self :: Error > where Self : Sized , F : FnMut (& Self :: Item) -> bool , { self . all (| e | ! f (e)) . map (| r | ! r) } # [doc = " Borrows an iterator, rather than consuming it."] # [doc = ""] # [doc = " This is useful to allow the application of iterator adaptors while still retaining ownership"] # [doc = " of the original adaptor."] # [inline] fn by_ref (& mut self) -> & mut Self where Self : Sized , { self } # [doc = " Returns the number of remaining elements in the iterator."] # [inline] fn count (mut self) -> Result < usize , Self :: Error > where Self : Sized , { let mut count = 0 ; while let Some (_) = self . next () ? { count += 1 ; } Ok (count) } # [doc = " Returns an iterator which filters elements by a predicate."] # [inline] fn filter < F > (self , f : F) -> Filter < Self , F > where Self : Sized , F : FnMut (& Self :: Item) -> bool , { Filter { it : self , f : f } } # [doc = " Returns the first element of the iterator which satisfies a predicate."] # [inline] fn find < F > (& mut self , mut f : F) -> Result < Option < & Self :: Item > , Self :: Error > where Self : Sized , F : FnMut (& Self :: Item) -> bool , { loop { self . advance () ? ; match self . get () { Some (v) => { if f (v) { break ; } } None => break , } } Ok ((* self) . get ()) } # [doc = " Calls a closure on each element of an iterator."] # [inline] fn for_each < F > (mut self , mut f : F) -> Result < () , Self :: Error > where Self : Sized , F : FnMut (& Self :: Item) , { while let Some (value) = self . next () ? { f (value) ; } Ok (()) } # [doc = " Returns an iterator which is well-behaved at the beginning and end of iteration."] # [inline] fn fuse (self) -> Fuse < Self > where Self : Sized , { Fuse { it : self , state : FuseState :: Start , } } # [doc = " Returns an iterator which applies a transform to elements."] # [inline] fn map < F , B > (self , f : F) -> Map < Self , F , B > where Self : Sized , F : FnMut (& Self :: Item) -> B , { Map { it : self , f : f , value : None , } } # [doc = " Returns an iterator which applies a transform to elements."] # [doc = ""] # [doc = " Unlike `map`, the the closure provided to this method returns a reference into the original"] # [doc = " value."] # [inline] fn map_ref < F , B : ? Sized > (self , f : F) -> MapRef < Self , F > where Self : Sized , F : Fn (& Self :: Item) -> & B , { MapRef { it : self , f : f } } # [doc = " Returns an iterator that applies a transform to errors."] # [inline] fn map_err < F , B > (self , f : F) -> MapErr < Self , F > where Self : Sized , F : Fn (Self :: Error) -> B , { MapErr { it : self , f : f } } # [doc = " Returns the `nth` element of the iterator."] # [inline] fn nth (& mut self , n : usize) -> Result < Option < & Self :: Item > , Self :: Error > { for _ in 0 .. n { self . advance () ? ; if let None = self . get () { return Ok (None) ; } } self . next () } # [doc = " Returns the position of the first element matching a predicate."] # [inline] fn position < F > (& mut self , mut f : F) -> Result < Option < usize > , Self :: Error > where Self : Sized , F : FnMut (& Self :: Item) -> bool , { let mut pos = 0 ; while let Some (v) = self . next () ? { if f (v) { return Ok (Some (pos)) ; } pos += 1 ; } Ok (None) } # [doc = " Returns an iterator which skips the first `n` elements."] # [inline] fn skip (self , n : usize) -> Skip < Self > where Self : Sized , { Skip { it : self , n : n } } # [doc = " Returns an iterator which skips the first sequence of elements matching a predicate."] # [inline] fn skip_while < F > (self , f : F) -> SkipWhile < Self , F > where Self : Sized , F : FnMut (& Self :: Item) -> bool , { SkipWhile { it : self , f : f , done : false , } } # [doc = " Returns an iterator which only returns the first `n` elements."] # [inline] fn take (self , n : usize) -> Take < Self > where Self : Sized , { Take { it : self , n : n , done : false , } } # [doc = " Returns an iterator which only returns the first sequence of elements matching a predicate."] # [inline] fn take_while < F > (self , f : F) -> TakeWhile < Self , F > where Self : Sized , F : FnMut (& Self :: Item) -> bool , { TakeWhile { it : self , f : f , done : false , } } }
    };
}

FallibleStreamingIterator!();